'use strict';
const purchaseId=new URLSearchParams(location.search).get('id');
const $p=s=>document.querySelector(s);
const fullKey='kashier.purchase-reversal-draft.'+purchaseId,partialKey='kashier.purchase-return-draft.'+purchaseId;
const money=value=>new Intl.NumberFormat('en-US').format(typeof value==='string'&&/^-?\d+$/.test(value)?BigInt(value):value);
const qty=value=>new Intl.NumberFormat('en-US',{maximumFractionDigits:3}).format(Number(value)/1000);
const when=value=>new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(value));
function uuid(){if(globalThis.crypto?.randomUUID)return globalThis.crypto.randomUUID();const b=new Uint8Array(16);globalThis.crypto.getRandomValues(b);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=[...b].map(x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);}
function read(key){try{return JSON.parse(sessionStorage.getItem(key)||'null');}catch{return null;}}
function save(key,value){try{if(value)sessionStorage.setItem(key,JSON.stringify(value));else sessionStorage.removeItem(key);return true;}catch{return false;}}
function status(selector,text){const e=$p(selector);if(e)e.textContent=text||'';}
function badge(id,className,text,attempt=0){const paper=$p('#receipt');if((!paper||paper.hidden)&&attempt<40){requestAnimationFrame(()=>badge(id,className,text,attempt+1));return;}if(!paper||paper.hidden)return;let e=$p('#'+id);if(!e){e=document.createElement('div');e.id=id;e.className=className;paper.insertBefore(e,paper.children[2]||null);}e.textContent=text;}
function parseQty(value){const m=/^(\d{1,8})(?:\.(\d{1,3}))?$/.exec(String(value||'').trim());if(!m)return null;const units=Number(m[1])*1000+Number((m[2]||'').padEnd(3,'0'));return Number.isSafeInteger(units)&&units>0&&units<=10000000?units:null;}
function returnedMap(returns){const map=new Map();for(const r of returns)for(const line of r.lines||[]){const n=Number(line.line_no),v=Number(line.quantity_units);map.set(n,(map.get(n)||0)+v);}return map;}
function eligible(purchase,finance){if(purchase.accounting_mode==='tracked'){if(!purchase.supplier_id||Number(purchase.amount_paid)+Number(purchase.debt_amount)!==Number(purchase.total))return {ok:false,message:'دۆخی دارایی ئەم کڕینە بۆ گەڕاندنەوە پشتڕاست نییە.'};if(Number(purchase.debt_amount)>0){if(!finance||finance.purchase_id!==purchase.id||finance.accounting_mode!=='tracked'||BigInt(finance.original_debt)!==BigInt(purchase.debt_amount))return {ok:false,message:'حسابی قەرزی ئەم پسوولەی کڕینە پشتڕاست نەکرایەوە؛ گەڕاندنەوە وەستێنرا.'};}}return {ok:true};}
function splitText(total,finance){const value=BigInt(total),outstanding=BigInt(finance?.outstanding||0),debt=value<outstanding?value:outstanding,cash=value-debt;return {debt,cash,text:'قەرزی هەڵوەشاوە: '+money(debt.toString())+' دینار · پارەی گەڕاوە بۆ قاسە: '+money(cash.toString())+' دینار'};}
function renderHistory(returns){const box=$p('#purchase-return-history');box.replaceChildren();for(const r of returns){const item=document.createElement('div'),debt=BigInt(r.debt_reversed||0),cash=BigInt(r.cash_refund||0);item.className='return-history-item';item.textContent='PPR-'+r.return_no+' · '+when(r.created_at)+' · کۆ: '+money(r.total)+' دینار · قەرزی هەڵوەشاوە: '+money(debt.toString())+' دینار · پارەی گەڕاوە بۆ قاسە: '+money(cash.toString())+' دینار · هۆکار: '+r.reason;box.append(item);}}
function renderPartial(purchase,finance,full,returns,error=''){
 const panel=$p('#purchase-return-panel'),form=$p('#purchase-return-form'),info=$p('#purchase-return-info'),lines=$p('#purchase-return-lines');panel.hidden=false;form.hidden=true;lines.replaceChildren();status('#purchase-return-status','');renderHistory(returns||[]);
 if(error){info.textContent='دۆخی گەڕاندنەوەی بەشی پشتڕاست نەکرایەوە.';status('#purchase-return-status',error);return;}
 if(full){save(partialKey,null);info.textContent='ئەم کڕینە پێشتر بە تەواوی گەڕێندراوەتەوە؛ گەڕاندنەوەی بەشی قوفڵە.';return;}
 const gate=eligible(purchase,finance);if(!gate.ok){info.textContent=gate.message;return;}
 const returned=returnedMap(returns),draft=read(partialKey),draftLines=new Map((draft?.lines||[]).map(x=>[Number(x.line_no),Number(x.quantity_units)]));let remainingCount=0;
 (purchase.lines||[]).forEach((line,index)=>{const lineNo=index+1,original=Number(line.quantity_units),done=returned.get(lineNo)||0,remaining=Math.max(0,original-done),row=document.createElement('div');row.className='return-line'+(remaining===0?' exhausted':'');const text=document.createElement('div'),strong=document.createElement('strong'),small=document.createElement('small');strong.textContent=line.name||('هێڵی '+lineNo);small.textContent='کڕدراو: '+qty(original)+' · گەڕاوە: '+qty(done)+' · ماوە: '+qty(remaining);text.append(strong,small);row.append(text);if(remaining>0){remainingCount++;const input=document.createElement('input');input.type='number';input.min='0';input.max=String(remaining/1000);input.step='0.001';input.inputMode='decimal';input.placeholder='0';input.dataset.lineNo=String(lineNo);const restored=draftLines.get(lineNo);if(restored)input.value=String(restored/1000);row.append(input);}lines.append(row);});
 if(returns.length){const total=returns.reduce((a,r)=>a+BigInt(r.total),0n),debt=returns.reduce((a,r)=>a+BigInt(r.debt_reversed||0),0n),cash=returns.reduce((a,r)=>a+BigInt(r.cash_refund||0),0n);badge('purchase-partial-badge','receipt-partial-returned','گەڕاندنەوەی بەشی کڕین: '+returns.length+' تۆمار · کۆ '+money(total.toString())+' · قەرز '+money(debt.toString())+' · قاسە '+money(cash.toString())+' دینار');}
 if(!remainingCount){info.textContent='هەموو بڕی ئەم پسوولەی کڕینە گەڕێندراوەتەوە.';save(partialKey,null);return;}
 form.hidden=false;
 if(purchase.accounting_mode==='tracked'&&BigInt(purchase.debt_amount||0)>0n)info.textContent='قەرزی ماوەی ئەم کڕینە: '+money(finance.outstanding)+' دینار. گەڕاندنەوە سەرەتا ئەو قەرزە کەم دەکات؛ ئەگەر بڕی گەڕاندنەوە لە قەرزی ماوە زیاتر بوو، زیادەکە پارەی گەڕاوە بۆ قاسە دەبێت.';
 else if(purchase.accounting_mode==='tracked')info.textContent='بڕی کاڵای دەتەوێت بگەڕێنیت دیاری بکە؛ چونکە قەرزی ماوە نییە، بڕی گەڕاندنەوە پارەی گەڕاوە بۆ قاسە دەبێت.';
 else info.textContent='بڕی کاڵای دەتەوێت بگەڕێنیت دیاری بکە؛ تەنها کۆگا کەم دەبێتەوە و هیچ پارە یان قەرزێک دروست نابێت.';
 if(draft){$p('#purchase-return-reason').value=draft.reason||'';status('#purchase-return-status','داواکاریی پێشوو کۆتاییەکەی پشتڕاست نەبوو؛ هەمان ناسنامە و هەمان بڕەکان بۆ دووبارەهەوڵدان پارێزراون.');}
}
function renderFull(purchase,finance,full,returns,error=''){
 const panel=$p('#purchase-reversal-panel'),form=$p('#purchase-reversal-form'),info=$p('#purchase-reversal-info');panel.hidden=false;form.hidden=true;status('#purchase-reversal-status','');
 if(error){info.textContent='دۆخی گەڕاندنەوەی تەواو پشتڕاست نەکرایەوە.';status('#purchase-reversal-status',error);return;}
 if(full){save(fullKey,null);info.textContent='ئەم کڕینە بە تەواوی گەڕێندراوەتەوە · PRV-'+full.reversal_no+' · '+when(full.created_at)+' · کۆ: '+money(full.total)+' دینار · قەرزی هەڵوەشاوە: '+money(full.debt_reversed||0)+' دینار · پارەی گەڕاوە بۆ قاسە: '+money(full.cash_refund)+' دینار · هۆکار: '+full.reason;badge('purchase-reversal-badge','receipt-reversed','کڕین گەڕێندراوەتەوە · PRV-'+full.reversal_no+' · قەرز '+money(full.debt_reversed||0)+' · قاسە '+money(full.cash_refund)+' دینار');return;}
 if(returns.length){save(fullKey,null);info.textContent='ئەم کڕینە '+returns.length+' گەڕاندنەوەی بەشی هەیە؛ بۆ پاراستنی تۆماری حساب، گەڕاندنەوەی تەواو قوفڵە.';return;}
 const gate=eligible(purchase,finance);if(!gate.ok){info.textContent=gate.message;return;}
 form.hidden=false;
 if(purchase.accounting_mode==='tracked'){const split=splitText(purchase.total,finance);info.textContent='هەموو کاڵاکان لە کۆگا کەم دەبنەوە. بە دۆخی حسابی ئێستا: '+split.text+'. تۆماری کڕینی سەرەکی ناسڕێتەوە.';}
 else info.textContent='هەموو کاڵاکانی ئەم پسوولەیە لە کۆگا کەم دەبنەوە؛ هیچ پارە یان قەرزێک دروست نابێت.';
 const draft=read(fullKey);if(draft){$p('#purchase-reversal-reason').value=draft.reason||'';status('#purchase-reversal-status','داواکاریی پێشوو کۆتاییەکەی پشتڕاست نەبوو؛ دووبارەهەوڵدان هەمان ناسنامە بەکاردەهێنێت.');}
}
async function load(){if(!$p('#purchase-reversal-panel'))return;if(!KashierData.loggedIn()){$p('#purchase-return-panel').hidden=true;$p('#purchase-reversal-panel').hidden=true;return;}$p('#purchase-return-panel').hidden=false;$p('#purchase-reversal-panel').hidden=false;status('#purchase-return-status','');status('#purchase-reversal-status','');try{const [purchase,full,returns,finance]=await Promise.all([KashierData.getPurchase(purchaseId),KashierPurchaseReversal.get(purchaseId),KashierPurchaseReversal.listReturns(purchaseId),KashierPurchasePayment.getFinance(purchaseId)]);renderPartial(purchase,finance,full,returns);renderFull(purchase,finance,full,returns);}catch(error){renderPartial({},null,null,[],(globalThis.KashierLocale?.message(error.message)??error.message));renderFull({},null,null,[],(globalThis.KashierLocale?.message(error.message)??error.message));}}
$p('#purchase-return-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=$p('#purchase-return-submit');if(button.disabled)return;const reason=$p('#purchase-return-reason').value.trim();if(!reason){status('#purchase-return-status','هۆکاری گەڕاندنەوە بنووسە.');return;}const selected=[];for(const input of $p('#purchase-return-lines').querySelectorAll('input[data-line-no]')){if(!String(input.value).trim()||Number(input.value)===0)continue;const units=parseQty(input.value);if(!units){status('#purchase-return-status','بڕی هەر کاڵایەک تا سێ خانەی دەیی بنووسە.');return;}selected.push({line_no:Number(input.dataset.lineNo),quantity_units:units});}if(!selected.length){status('#purchase-return-status','لانیکەم یەک کاڵا و بڕێکی زیاتر لە سفر هەڵبژێرە.');return;}let draft=read(partialKey);const candidate={id:draft?.id||uuid(),reason,lines:selected};if(draft&&JSON.stringify({reason:draft.reason,lines:draft.lines})!==JSON.stringify({reason,lines:selected})){status('#purchase-return-status','داواکاریی ماوە بڕ یان هۆکاری جیاوازی هەیە؛ بڕە پێشووەکان بگەڕێنەوە یان پەڕەکە نوێ بکەرەوە.');return;}draft=candidate;if(!save(partialKey,draft)){status('#purchase-return-status','ناسنامەی پارێزراوی داواکاری هەڵنەگیرا؛ کردارەکە نەنێردرا.');return;}if(!confirm('دڵنیایت لە گەڕاندنەوەی بڕە هەڵبژێردراوەکان؟ قەرزی ماوە سەرەتا هەڵدەوەشێتەوە و زیادەکە پارەی قاسە دەبێت.'))return;button.disabled=true;status('#purchase-return-status','تۆمارکردنی گەڕاندنەوەی بەشی…');try{const result=await KashierPurchaseReversal.postReturn({p_id:draft.id,p_purchase:purchaseId,p_reason:draft.reason,p_lines:draft.lines});if(!result?.id||result.id!==draft.id)throw new Error('وەڵامی گەڕاندنەوە پشتڕاست نەکرایەوە.');save(partialKey,null);$p('#purchase-return-reason').value='';await load();}catch(error){if(error.status&&error.status<500&&error.code!=='purchase_return_request_conflict')save(partialKey,null);status('#purchase-return-status',(globalThis.KashierLocale?.message(error.message)??error.message));}finally{button.disabled=false;}});
$p('#purchase-reversal-form')?.addEventListener('submit',async event=>{event.preventDefault();const button=$p('#purchase-reversal-submit');if(button.disabled)return;const reason=$p('#purchase-reversal-reason').value.trim();if(!reason){status('#purchase-reversal-status','هۆکاری گەڕاندنەوە بنووسە.');return;}let draft=read(fullKey);if(!draft){draft={id:uuid(),reason};if(!save(fullKey,draft)){status('#purchase-reversal-status','ناسنامەی پارێزراوی داواکاری هەڵنەگیرا؛ کردارەکە نەنێردرا.');return;}}else if(draft.reason!==reason){status('#purchase-reversal-status','داواکاریی ماوە هۆکاری جیاوازی هەیە؛ هۆکاری پێشوو بەکاربهێنە.');return;}if(!confirm('دڵنیایت لە گەڕاندنەوەی تەواوی ئەم کڕینە؟ قەرزی ماوە سەرەتا هەڵدەوەشێتەوە و زیادەکە پارەی قاسە دەبێت.'))return;button.disabled=true;status('#purchase-reversal-status','تۆمارکردنی گەڕاندنەوەی تەواو…');try{const result=await KashierPurchaseReversal.post({p_id:draft.id,p_purchase:purchaseId,p_reason:draft.reason});if(!result?.id||result.id!==draft.id)throw new Error('وەڵامی گەڕاندنەوە پشتڕاست نەکرایەوە.');save(fullKey,null);$p('#purchase-reversal-reason').value='';await load();}catch(error){if(error.status&&error.status<500&&error.code!=='purchase_reversal_request_conflict')save(fullKey,null);status('#purchase-reversal-status',(globalThis.KashierLocale?.message(error.message)??error.message));}finally{button.disabled=false;}});
window.addEventListener('kashier:purchase-finance-changed',()=>load());
load();
